CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schools(id text PRIMARY KEY,name text NOT NULL,country char(2) NOT NULL,region text,student_email_domain text UNIQUE);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,birth_date date NOT NULL,password_salt text NOT NULL,password_hash text NOT NULL,school_id text REFERENCES schools(id),school_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,display_name text NOT NULL DEFAULT '',bio text NOT NULL DEFAULT '',avatar_url text,social_links jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS friend_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requester_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,status text NOT NULL CHECK(status IN('pending','accepted','declined','blocked')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(requester_id,recipient_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS creation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,era text NOT NULL,role text NOT NULL,input_asset_url text,status text NOT NULL DEFAULT 'queued',output_asset_url text,safety_status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),reported_user_id uuid REFERENCES users(id),message_id uuid REFERENCES messages(id),reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS school_verification_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,school_id text NOT NULL REFERENCES schools(id),status text NOT NULL DEFAULT 'manual_review_required',method text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
